css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-sk{width:min(1020px,100%);display:grid;gap:1.6em}
.fx-sk .top{display:flex;justify-content:space-between;align-items:end;gap:1em;flex-wrap:wrap}.fx-sk h2{font-size:clamp(1.8em,4vw,2.6em)}
.fx-sk .rb{padding:.6em 1.2em;border-radius:99px;border:1.5px solid var(--primary);background:transparent;color:var(--primary);font:700 .88em var(--font-body);cursor:pointer;transition:background .25s,color .25s}
.fx-sk .rb:hover{background:var(--primary);color:var(--on-primary)}.fx-sk .rb:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-sk .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.2em}
.fx-sk .card{border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 94%,var(--text));display:grid}
.fx-sk .card>.fx-art,.fx-sk .im{aspect-ratio:16/10}
.fx-sk .body{padding:1.1em 1.2em 1.3em;display:grid;gap:.6em}.fx-sk h3{font-size:1.2em}.fx-sk .body p{opacity:.7;font-size:.93em}
.fx-sk .by{display:flex;align-items:center;gap:.7em;margin-top:.4em}.fx-sk .by small{opacity:.6}
.fx-sk .av{width:2em;height:2em;border-radius:50%;flex:none}.fx-sk .av::before,.fx-sk .av::after{display:none}
.fx-sk .sk{background:linear-gradient(100deg,color-mix(in srgb,var(--text) 8%,var(--surface)) 30%,color-mix(in srgb,var(--text) 15%,var(--surface)) 50%,color-mix(in srgb,var(--text) 8%,var(--surface)) 70%);background-size:300% 100%;animation:fxsksh calc(1.5s/var(--speed)) ease-in-out infinite}
.fx-sk .ln{height:.9em;border-radius:99px}.fx-sk .ln.w60{width:60%;height:1.15em}.fx-sk .ln.w80{width:80%}.fx-sk .ln.w40{width:40%}
.fx-sk.loaded .real .card{animation:fxskin calc(.6s/var(--speed)) ease both}.fx-sk .grid>div{display:grid}
@keyframes fxsksh{from{background-position:100% 0}to{background-position:0 0}}
@keyframes fxskin{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@media(max-width:820px){.fx-sk .grid{grid-template-columns:1fr 1fr}.fx-sk .grid>div:nth-child(3){display:none}}
@media(max-width:520px){.fx-sk .grid{grid-template-columns:1fr}.fx-sk .grid>div:nth-child(2){display:none}}
@media(prefers-reduced-motion:reduce){.fx-sk .sk{animation:none}.fx-sk.loaded .real .card{animation:none}}
/* touch: :hover mirrored as .is-tap */
.fx-sk .rb.is-tap{background:var(--primary);color:var(--on-primary)}

js:
(function(){document.querySelectorAll('.fx-sk').forEach(function(r){var b=r.querySelector('.rb'),t;
function sp(){return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--speed'))||1}
function set(l){r.classList.toggle('loaded',l);r.setAttribute('aria-busy',!l);r.querySelectorAll('.real').forEach(function(e){e.style.display=l?'contents':'none'});
r.querySelectorAll('.skl').forEach(function(e){e.style.display=l?'none':'contents'})}
function run(){clearTimeout(t);set(false);t=setTimeout(function(){set(true)},2400/sp())}
b.addEventListener('click',run);run()})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
